pub fn fr_w() -> i32 {
    // cells of a row
    return 36;
}
pub fn fr_npred() -> i32 {
    return 10;
}
pub fn fr_number(row: i32) -> i32 {
    return FR_ROWS[(row * 36 + 0) as usize];
}
pub fn fr_block(row: i32) -> i32 {
    return FR_ROWS[(row * 36 + 1) as usize];
}
pub fn fr_winner(row: i32) -> i32 {
    return FR_ROWS[(row * 36 + 2) as usize];
}
pub fn fr_reason(row: i32) -> i32 {
    return FR_ROWS[(row * 36 + 3) as usize];
}
pub fn fr_flags(row: i32) -> i32 {
    return FR_ROWS[(row * 36 + 4) as usize];
}
pub fn fr_conf(row: i32) -> i32 {
    return FR_ROWS[(row * 36 + 5) as usize];
}
pub fn fr_pcol(row: i32, k: i32) -> i32 {
    return FR_ROWS[(row * 36 + (6 + (k * 3))) as usize];
}
pub fn fr_pcmp(row: i32, k: i32) -> i32 {
    return FR_ROWS[(row * 36 + (7 + (k * 3))) as usize];
}
pub fn fr_pset(row: i32, k: i32) -> i32 {
    return FR_ROWS[(row * 36 + (8 + (k * 3))) as usize];
}
pub fn fr_defence(row: i32) -> i32 {
    // The defence of SPEC 9.5 a row of block 200 is (1-6, by the tens digit of its number minus 19; 24x is the seals', 5), 0 for every other row.
    if fr_block(row) != 200 {
        return 0;
    }
    return (fr_number(row) / 10) - 19;
}
pub fn fr_order(k: i32) -> i32 {
    // The k-th block a word group is tried against (D224); -1 after the last.
    if k == 0 {
        return 400;
    }
    if k == 1 {
        return 600;
    }
    if k == 2 {
        return 200;
    }
    if k == 3 {
        return 300;
    }
    if k == 4 {
        return 100;
    }
    return -1;
}
pub(crate) fn fr_holds(row: i32, gv: &mut crate::port::Cells) -> i32 {
    // 1 when every predicate of `row` holds on the group columns `gv`.
    let mut k: i32 = 0;
    let mut col: i32 = 0;
    let mut v: i32 = 0;
    let mut s: i32 = 0;
    let mut c: i32 = 0;
    while k < fr_npred() {
        col = fr_pcol(row, k);
        if col >= 0 {
            v = crate::port::cells_at(gv, col);
            s = fr_setting(fr_pset(row, k));
            c = fr_pcmp(row, k);
            if (c == fc_eq()) && (v != s) {
                return 0;
            }
            if (c == fc_ne()) && (v == s) {
                return 0;
            }
            if (c == fc_ge()) && ((v < 0) || (v < s)) {
                return 0;
            }
            if (c == fc_lt()) && ((v < 0) || (v >= s)) {
                return 0;
            }
        }
        k += 1;
    }
    return 1;
}
pub fn fr_decide(gv: &mut crate::port::Cells) -> i32 {
    // The row (an index of `fr-rows`) of the first rule that holds on the group columns `gv`, trying the blocks in `fr-order` and the
    // rows of a block in table order; -1 when none holds (the default row 190 holds for every group, so never in practice).
    let n: i32 = 66;
    let mut b: i32 = 0;
    let mut blk: i32 = 0;
    let mut r: i32 = 0;
    while fr_order(b) >= 0 {
        blk = fr_order(b);
        r = 0;
        while r < n {
            if fr_block(r) == blk {
                if fr_holds(r, gv) == 1 {
                    return r;
                }
            }
            r += 1;
        }
        b += 1;
    }
    return -1;
}
pub fn fr_decide_block(gv: &mut crate::port::Cells, blk: i32) -> i32 {
    // The row (an index of `fr-rows`) of the first rule OF BLOCK `blk` that holds on the measures `gv`; -1 when none does. Block 500 reads the graphics
    // measures (`gmz`, codes 100 and up, in a vector of 128 cells), which have a default row (599) so that the answer is never -1 there.
    let n: i32 = 66;
    let mut r: i32 = 0;
    while r < n {
        if fr_block(r) == blk {
            if fr_holds(r, gv) == 1 {
                return r;
            }
        }
        r += 1;
    }
    return -1;
}
